// The rebuilt cover (public/media/cover/cover.svg, generated by tools/cover/build_cover.py) read as data:
// every etched stroke as geometry (for the relief renderer), and every binary group with its strokes in
// document order (for The Key and later chapters). Pure: no DOM, so the same code runs in Node and the
// browser. The stroke KIND (across or along its line of writing) is measured from the geometry here, never
// read from the SVG's class names; the tests compare the two.

/** One parsed XML element (text is dropped). */
interface El {
  tag: string;
  attrs: Record<string, string>;
  children: El[];
}

/** Minimal XML reader for the generated SVG: elements, attributes, comments and declarations. */
function parseXml(src: string): El {
  const root: El = { tag: '#root', attrs: {}, children: [] };
  const stack: El[] = [root];
  const re = /<!--[\s\S]*?-->|<\?[\s\S]*?\?>|<\/([A-Za-z][\w:-]*)\s*>|<([A-Za-z][\w:-]*)((?:\s+[\w:.-]+\s*=\s*"[^"]*")*)\s*(\/?)>/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(src)) !== null) {
    if (m[0].startsWith('<!--') || m[0].startsWith('<?')) continue;
    if (m[1]) {
      const top = stack.pop();
      if (!top || top.tag !== m[1]) throw new Error(`cover.svg: mismatched closing tag ${m[1]}`);
      continue;
    }
    const attrs: Record<string, string> = {};
    const ar = /([\w:.-]+)\s*=\s*"([^"]*)"/g;
    let a: RegExpExecArray | null;
    while ((a = ar.exec(m[3] ?? '')) !== null) attrs[a[1] as string] = a[2] ?? '';
    const el: El = { tag: m[2] as string, attrs, children: [] };
    (stack[stack.length - 1] as El).children.push(el);
    if (m[4] !== '/') stack.push(el);
  }
  if (stack.length !== 1) throw new Error('cover.svg: unclosed elements');
  const svg = root.children[0];
  if (!svg) throw new Error('cover.svg: empty document');
  return svg;
}

export type Pt = [number, number];

/** A drawable etched mark in millimetres: a polyline (M/L/Z paths) or a circle; `fill` for the solid dots. */
export type Drawable =
  | { kind: 'poly'; pts: Pt[]; closed: boolean; width: number }
  | { kind: 'circle'; cx: number; cy: number; r: number; width: number; fill: boolean };

export type StrokeKind = 'across' | 'along';

export interface Bit {
  /** Position in the group, most significant first (the SVG's document order and data-index). */
  index: number;
  row: number;
  a: Pt;
  b: Pt;
  /** The direction of writing at this stroke (unit vector), from the neighbouring strokes. */
  writing: Pt;
  /** Angle between the stroke and its line of writing, degrees, 0 to 90. */
  angleDeg: number;
  /** Measured from the geometry: a stroke more than 45 degrees from its line of writing is "across". */
  kind: StrokeKind;
  /** The SVG generator's own label (class "bit one" or "bit zero"); used only by tests. */
  svgClass: 'one' | 'zero';
}

export interface BinaryGroup {
  /** The innermost data-id that holds the strokes, e.g. record.rotationPeriod, pulsar.3.digits, hydrogen.one. */
  id: string;
  /** The data-binary the SVG generator wrote on this group or its parent (for tests), or null. */
  svgBinary: string | null;
  bits: Bit[];
  /** Centre of the strokes, mm. */
  centre: Pt;
}

export interface CoverModel {
  /** Size of the cover in mm (the viewBox is 0 0 size size). */
  size: number;
  drawables: Drawable[];
  groups: BinaryGroup[];
}

const num = (s: string | undefined): number => {
  const v = Number(s);
  if (!Number.isFinite(v)) throw new Error(`cover.svg: not a number: ${s}`);
  return v;
};

/** M/L/Z path data (the generator writes nothing else) as polylines. */
export function parsePathD(d: string): { pts: Pt[]; closed: boolean }[] {
  const out: { pts: Pt[]; closed: boolean }[] = [];
  const re = /([MLZ])\s*([-\d.eE]+)?[\s,]*([-\d.eE]+)?/g;
  let m: RegExpExecArray | null;
  let cur: { pts: Pt[]; closed: boolean } | null = null;
  while ((m = re.exec(d)) !== null) {
    const c = m[1];
    if (c === 'Z') {
      if (cur) cur.closed = true;
      continue;
    }
    const p: Pt = [num(m[2]), num(m[3])];
    if (c === 'M' || !cur) {
      cur = { pts: [p], closed: false };
      out.push(cur);
    } else cur.pts.push(p);
  }
  if (/[^MLZ\d\s.,eE-]/.test(d)) throw new Error(`cover.svg: unsupported path command in ${d.slice(0, 40)}`);
  return out;
}

function walk(el: El, fn: (e: El, parents: El[]) => void, parents: El[] = []): void {
  fn(el, parents);
  for (const c of el.children) walk(c, fn, [...parents, el]);
}

const isBit = (e: El): boolean => /\bbit\b/.test(e.attrs.class ?? '');
const hasClass = (e: El, c: string): boolean => new RegExp(`\\b${c}\\b`).test(e.attrs.class ?? '');

function unit(v: Pt): Pt {
  const n = Math.hypot(v[0], v[1]);
  return n > 0 ? [v[0] / n, v[1] / n] : [1, 0];
}

const mid = (a: Pt, b: Pt): Pt => [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2];
const sub = (a: Pt, b: Pt): Pt => [a[0] - b[0], a[1] - b[1]];

/** Angle between two lines (undirected), degrees 0 to 90. */
export function lineAngleDeg(u: Pt, v: Pt): number {
  const a = unit(u);
  const b = unit(v);
  const c = Math.min(1, Math.abs(a[0] * b[0] + a[1] * b[1]));
  return (Math.acos(c) * 180) / Math.PI;
}

/** Average of undirected directions (doubling the angle so opposite vectors agree). */
function meanAxis(dirs: Pt[]): Pt {
  let cx = 0;
  let cy = 0;
  for (const d of dirs) {
    const t = 2 * Math.atan2(d[1], d[0]);
    cx += Math.cos(t);
    cy += Math.sin(t);
  }
  const t = Math.atan2(cy, cx) / 2;
  return [Math.cos(t), Math.sin(t)];
}

interface RawBit {
  index: number;
  row: number;
  a: Pt;
  b: Pt;
  svgClass: 'one' | 'zero';
}

/**
 * The direction of writing at each stroke: the line through the centres of its neighbours in the same row
 * (previous and next stroke; one-sided at the ends). A row of one stroke has no direction of its own and
 * gets the fallback.
 */
function writingDirections(bits: RawBit[], fallback: Pt | null): Pt[] {
  const rows = new Map<number, RawBit[]>();
  for (const b of bits) {
    const r = rows.get(b.row) ?? [];
    r.push(b);
    rows.set(b.row, r);
  }
  const out = new Map<number, Pt>();
  for (const row of rows.values()) {
    row.sort((p, q) => p.index - q.index);
    for (let i = 0; i < row.length; i++) {
      const prev = row[Math.max(0, i - 1)] as RawBit;
      const next = row[Math.min(row.length - 1, i + 1)] as RawBit;
      if (prev === next) {
        if (!fallback) throw new Error('a single stroke with no line of writing to compare it with');
        out.set((row[i] as RawBit).index, fallback);
      } else out.set((row[i] as RawBit).index, unit(sub(mid(next.a, next.b), mid(prev.a, prev.b))));
    }
  }
  return bits.map((b) => out.get(b.index) as Pt);
}

/** Parse cover.svg into drawables and binary groups. */
export function parseCoverSvg(text: string): CoverModel {
  const svg = parseXml(text);
  const vb = (svg.attrs.viewBox ?? '').split(/\s+/).map(Number);
  const size = vb[2] ?? NaN;
  if (!Number.isFinite(size)) throw new Error('cover.svg: no viewBox');

  const drawables: Drawable[] = [];
  /** Innermost data-id group -> its raw bits; and the group elements themselves. */
  const rawGroups = new Map<string, { el: El; parent: El | undefined; bits: RawBit[] }>();
  walk(svg, (e, parents) => {
    if (e.tag === 'path' && e.attrs.d) {
      const width = num(e.attrs['stroke-width'] ?? '0.3');
      for (const p of parsePathD(e.attrs.d)) drawables.push({ kind: 'poly', pts: p.pts, closed: p.closed, width });
    } else if (e.tag === 'circle') {
      drawables.push({
        kind: 'circle', cx: num(e.attrs.cx), cy: num(e.attrs.cy), r: num(e.attrs.r),
        width: num(e.attrs['stroke-width'] ?? '0'), fill: hasClass(e, 'dot'),
      });
    }
    if (!isBit(e)) return;
    const gi = [...parents].reverse().findIndex((p) => p.attrs['data-id'] !== undefined);
    if (gi < 0) throw new Error('cover.svg: a bit outside any data-id group');
    const owner = parents[parents.length - 1 - gi] as El;
    const ownerParent = parents[parents.length - 2 - gi];
    const rowEl = [...parents].reverse().find((p) => hasClass(p, 'row'));
    const seg = parsePathD(e.attrs.d ?? '')[0];
    if (!seg || seg.pts.length !== 2) throw new Error('cover.svg: a bit must be one straight stroke');
    const id = owner.attrs['data-id'] as string;
    const g = rawGroups.get(id) ?? { el: owner, parent: ownerParent, bits: [] };
    g.bits.push({
      index: num(e.attrs['data-index']),
      row: rowEl ? num(rowEl.attrs['data-row']) : 0,
      a: seg.pts[0] as Pt,
      b: seg.pts[1] as Pt,
      svgClass: hasClass(e, 'one') ? 'one' : 'zero',
    });
    rawGroups.set(id, g);
  });

  // Fallback directions for one-stroke groups. Strings drawn side by side in one drawing (the picture line
  // labels) share their line of writing; the single stroke of the hydrogen drawing sits on the line that
  // joins the drawing's two atoms.
  const entries = [...rawGroups.entries()];
  const siblingAxis = (parent: El | undefined, self: string): Pt | null => {
    const dirs: Pt[] = [];
    for (const [id, g] of entries) {
      if (id === self || g.parent !== parent || g.bits.length < 2) continue;
      const w = writingDirections(g.bits, null);
      dirs.push(...w);
    }
    return dirs.length ? meanAxis(dirs) : null;
  };
  const atomsAxis = (parent: El | undefined): Pt | null => {
    if (!parent) return null;
    const centres: Pt[] = [];
    for (const c of parent.children) {
      const circle = c.children.find((x) => x.tag === 'circle');
      if (c.attrs['data-id']?.includes('.state.') && circle) centres.push([num(circle.attrs.cx), num(circle.attrs.cy)]);
    }
    return centres.length === 2 ? unit(sub(centres[1] as Pt, centres[0] as Pt)) : null;
  };

  const groups: BinaryGroup[] = entries.map(([id, g]) => {
    g.bits.sort((p, q) => p.index - q.index);
    g.bits.forEach((b, i) => {
      if (b.index !== i) throw new Error(`cover.svg: data-index ${b.index} at position ${i} in ${id}`);
    });
    const fallback = g.bits.length === 1 ? (siblingAxis(g.parent, id) ?? atomsAxis(g.parent)) : null;
    const writing = writingDirections(g.bits, fallback);
    const bits: Bit[] = g.bits.map((b, i) => {
      const w = writing[i] as Pt;
      const angleDeg = lineAngleDeg(sub(b.b, b.a), w);
      return { ...b, writing: w, angleDeg, kind: angleDeg > 45 ? 'across' : 'along' };
    });
    const cs = bits.map((b) => mid(b.a, b.b));
    const centre: Pt = [cs.reduce((s, c) => s + c[0], 0) / cs.length, cs.reduce((s, c) => s + c[1], 0) / cs.length];
    const svgBinary = g.el.attrs['data-binary'] ?? g.parent?.attrs['data-binary'] ?? null;
    return { id, svgBinary, bits, centre };
  });
  return { size, drawables, groups };
}

/** A group's strokes as a string of kinds: 'x' across, '-' along (no meaning attached). */
export function strokeString(g: BinaryGroup): string {
  return g.bits.map((b) => (b.kind === 'across' ? 'x' : '-')).join('');
}
